How about quoting the system call arguments in back ticks and using a format similar to the ERRORS section of the [man pages](https://man7.org/linux/man-pages/man2/pivot_root.2.html):
```patch
diff --git a/kernel/src/fs/path/resolver.rs b/kernel/src/fs/path/resolver.rs
index a625f38f2..dbe2d932b 100644
--- a/kernel/src/fs/path/resolver.rs
+++ b/kernel/src/fs/path/resolver.rs
@@ -245,16 +245,19 @@ impl PathResolver {
         let put_old_path = self.lookup(&put_old_path)?;
 
         if new_root_path.type_() != InodeType::Dir || put_old_path.type_() != InodeType::Dir {
-            return_errno_with_message!(Errno::ENOTDIR, "new_root and put_old must be directories");
+            return_errno_with_message!(
+                Errno::ENOTDIR,
+                "`new_root` or `put_old` is not a directory"
+            );
         }
         if self.root.mount.id() == new_root_path.mount.id() {
-            return_errno_with_message!(Errno::EBUSY, "new_root is the current root");
+            return_errno_with_message!(Errno::EBUSY, "`new_root` is on the current root mount");
         }
         if !new_root_path.is_mount_root() {
-            return_errno_with_message!(Errno::EINVAL, "new_root must be a mountpoint");
+            return_errno_with_message!(Errno::EINVAL, "`new_root` is not a mount point");
         }
         if new_root_path.mount.parent().is_none() {
-            return_errno_with_message!(Errno::EINVAL, "cannot pivot_root to root mount");
+            return_errno_with_message!(Errno::EINVAL, "`new_root` is on the rootfs mount");
         }
 
         let current_ns_proxy = ctx.thread_local.borrow_ns_proxy();
@@ -262,21 +265,24 @@ impl PathResolver {
         if !current_mnt_ns.owns(&new_root_path.mount) || !current_mnt_ns.owns(&put_old_path.mount) {
             return_errno_with_message!(
                 Errno::EINVAL,
-                "new_root and put_old must be in the current mount namespace"
+                "`new_root` or `put_old` is not in the current mount namespace"
             );
         }
 
         if new_root_path.mount.id() != put_old_path.mount.id() {
             return_errno_with_message!(
                 Errno::EINVAL,
-                "put_old must be on the same mount as new_root"
+                "`put_old` is not on the same mount as `new_root`"
             );
         }
         if !put_old_path
             .dentry
             .is_equal_or_descendant_of(&new_root_path.dentry)
         {
-            return_errno_with_message!(Errno::EINVAL, "put_old must be underneath new_root");
+            return_errno_with_message!(
+                Errno::EINVAL,
+                "`put_old` is not at or underneath `new_root`"
+            );
         }
 
