In addition, I think you miss the following checks. If you don't check `self.root`, some panics below may be reachable.
```patch
diff --git a/kernel/src/fs/path/resolver.rs b/kernel/src/fs/path/resolver.rs
index dbe2d932b..cf2a15a98 100644
--- a/kernel/src/fs/path/resolver.rs
+++ b/kernel/src/fs/path/resolver.rs
@@ -250,14 +250,25 @@ impl PathResolver {
                 "`new_root` or `put_old` is not a directory"
             );
         }
-        if self.root.mount.id() == new_root_path.mount.id() {
-            return_errno_with_message!(Errno::EBUSY, "`new_root` is on the current root mount");
+        if self.root.mount.id() == new_root_path.mount.id()
+            || self.root.mount.id() == put_old_path.mount.id()
+        {
+            return_errno_with_message!(
+                Errno::EBUSY,
+                "`new_root` or `put_old` is on the current root mount"
+            );
         }
-        if !new_root_path.is_mount_root() {
-            return_errno_with_message!(Errno::EINVAL, "`new_root` is not a mount point");
+        if !new_root_path.is_mount_root() || !self.root.is_mount_root() {
+            return_errno_with_message!(
+                Errno::EINVAL,
+                "`new_root` or the current root is not a mount point"
+            );
         }
-        if new_root_path.mount.parent().is_none() {
-            return_errno_with_message!(Errno::EINVAL, "`new_root` is on the rootfs mount");
+        if new_root_path.mount.parent().is_none() || self.root.mount.parent().is_none() {
+            return_errno_with_message!(
+                Errno::EINVAL,
+                "`new_root` or the current root is on the rootfs mount"
+            );
         }
 
         let current_ns_proxy = ctx.thread_local.borrow_ns_proxy();
```


